// SLOT A. Block/weapon/ammo definitions from defs_stats.json (generated by tools/index_stats.py; see docs/stats.md).
// Field mapping (json path -> field) is listed in docs/sim-design.md section 8. Missing numbers: hard error unless a
// documented default exists (then the default is recorded in DefDb.Assumptions for the run header).
// A DefDb is immutable after Load, so one instance is shared by all worker threads (DefDb.LoadCached).
using System;
using System.Collections.Generic;
using System.IO;
using VRageMath;
using SeSim.Core;

namespace SeSim.Blueprint
{
    public sealed class BlockDef
    {
        public string Key, TypeId, Subtype, Kind;      // Kind = defs_stats "kind" (Thrust, Gyro, WeaponBlock, ...)
        public bool Large;
        public Vector3I SizeCells;
        public float MassKg, MaxIntegrity, CriticalIntegrity;
        public string PowerGroup; public float PowerMW;  // sink group + required power (stats.power_mw / required_power_mw)
        public float ThrustForceN, ThrustMaxPowerMW, ThrustMinPowerMW;
        public float GyroForce;
        public float BatteryMaxMWh, BatteryMaxOutMW, BatteryMaxInMW, BatteryInitialRatio;
        public float GeneratorMW;                      // reactors / hydrogen engines: constant output (fuel not modelled)
        public float SensorMaxRange, TurretControlRange;
        public float WarheadRadius, WarheadDamage;
        public float InventoryVolume;
        public WeaponDef Weapon;                          // null for non-weapons
        public bool IsTerminal;                           // has a terminal (everything except armor/structure)
        public override string ToString() { return Key; }
    }

    public sealed class WeaponDef
    {
        public string Id;                                 // "GatlingGun", "SmallRailgun", ...
        public float RateOfFireRpm; public int ShotsInBurst;
        public float DeviateShotAngleDeg, ShotDelayMs, ReloadTimeMs;
        public string MagazineId; public int MagazineCapacity; public float MagazineMass, MagazineVolume;
        public AmmoDef Ammo;
    }

    public sealed class AmmoDef
    {
        public string Id; public bool IsMissile;          // kind "Missile" (rockets, railgun slugs) vs "Projectile"
        public float Speed, MaxTrajectory, MassDamage, HealthDamage, ExplosiveDamageMultiplier;
        public float MissileInitialSpeed, MissileAcceleration, MissileExplosionRadius, MissileExplosionDamage, MissileHealthPool, MissileMass;
        public bool GravityEnabled;
    }

    public sealed class DefDb
    {
        public readonly Dictionary<string, BlockDef> Blocks = new Dictionary<string, BlockDef>();
        public readonly Dictionary<string, WeaponDef> Weapons = new Dictionary<string, WeaponDef>();
        public readonly Dictionary<string, AmmoDef> Ammo = new Dictionary<string, AmmoDef>();
        public readonly Dictionary<string, int> PowerPriority = new Dictionary<string, int>();
        /// <summary>Resource distribution group flags: true = adaptible (partial supply allowed), false = all or nothing.</summary>
        public readonly Dictionary<string, bool> PowerAdaptible = new Dictionary<string, bool>();
        public readonly List<string> Assumptions = new List<string>();

        // constants from defs_stats.json "constants" (degrees converted to radians where noted)
        public double SmallShipMaxSpeed = 100, LargeShipMaxSpeed = 100;
        public double SmallShipMaxAngularSpeedRad = 2 * Math.PI, LargeShipMaxAngularSpeedRad = Math.PI;
        public double SmallCellSize = 0.5, LargeCellSize = 2.5;

        static readonly object CacheLock = new object();
        static readonly Dictionary<string, DefDb> Cache = new Dictionary<string, DefDb>();

        /// <summary>Loads once per process and path (thread-safe); the result is read-only.</summary>
        public static DefDb LoadCached(string path)
        {
            string full = Path.GetFullPath(path);
            lock (CacheLock)
            {
                DefDb db;
                if (!Cache.TryGetValue(full, out db)) { db = Load(full); Cache[full] = db; }
                return db;
            }
        }

        public static DefDb Load(string defsStatsJsonPath)
        {
            object root = MiniJson.Parse(File.ReadAllText(defsStatsJsonPath));
            var db = new DefDb();

            // ---- constants ----
            var cons = MiniJson.Obj(root, "constants");
            if (cons == null) throw new InvalidDataException("defs_stats.json: no 'constants'");
            db.SmallShipMaxSpeed = MiniJson.Num(cons, "SmallShipMaxSpeed", 100);
            db.LargeShipMaxSpeed = MiniJson.Num(cons, "LargeShipMaxSpeed", 100);
            db.SmallShipMaxAngularSpeedRad = MiniJson.Num(cons, "SmallShipMaxAngularSpeed", 360) * Math.PI / 180.0;
            db.LargeShipMaxAngularSpeedRad = MiniJson.Num(cons, "LargeShipMaxAngularSpeed", 180) * Math.PI / 180.0;
            var cs = MiniJson.Obj(cons, "CubeSizeMeters");
            if (cs != null) { db.SmallCellSize = MiniJson.Num(cs, "Small", 0.5); db.LargeCellSize = MiniJson.Num(cs, "Large", 2.5); }
            var groups = MiniJson.Obj(cons, "PowerDistributionGroups");
            if (groups == null) throw new InvalidDataException("defs_stats.json: no constants.PowerDistributionGroups");
            foreach (var kv in groups)
            {
                if (kv.Key.StartsWith("_")) continue;
                db.PowerPriority[kv.Key] = (int)MiniJson.Num(kv.Value, "priority", 1000);
                db.PowerAdaptible[kv.Key] = MiniJson.Bool(kv.Value, "adaptible", false);
            }

            // ---- ammo (top level, keyed by ammo id) and magazines ----
            var ammoTop = MiniJson.Obj(root, "ammo");
            var mags = MiniJson.Obj(root, "magazines");
            var weaponsTop = MiniJson.Obj(root, "weapons");

            // ---- blocks ----
            var blocks = MiniJson.Obj(root, "blocks");
            if (blocks == null) throw new InvalidDataException("defs_stats.json: no 'blocks'");
            var defaulted = new HashSet<string>();
            foreach (var kv in blocks)
            {
                var e = kv.Value as Dictionary<string, object>;
                if (e == null) continue;
                var d = new BlockDef();
                d.Key = kv.Key;
                d.TypeId = MiniJson.Str(e, "type", "");
                d.Subtype = MiniJson.Str(e, "subtype", "");
                d.Kind = MiniJson.Str(e, "kind", "");
                d.Large = MiniJson.Str(e, "grid", "Small") == "Large";
                var sz = MiniJson.Arr(e, "size_cells");
                if (sz == null || sz.Count != 3) continue;           // blocks without a size cannot be placed; they are never referenced
                d.SizeCells = new Vector3I((int)(double)sz[0], (int)(double)sz[1], (int)(double)sz[2]);
                d.MassKg = (float)MiniJson.Num(e, "mass_kg", 0);
                var integ = MiniJson.Obj(e, "integrity");
                double sum = MiniJson.Num(integ, "sum_of_components", 0);
                double expl = MiniJson.Num(integ, "explicit_MaxIntegrity_override", 0);
                d.MaxIntegrity = (float)(expl > 0 ? expl : sum);
                d.CriticalIntegrity = (float)MiniJson.Num(integ, "integrity_before_critical_component", 0);
                if (d.CriticalIntegrity > d.MaxIntegrity) d.CriticalIntegrity = d.MaxIntegrity;
                d.IsTerminal = d.Kind != "CubeBlock";
                d.InventoryVolume = 0;

                var st = MiniJson.Obj(e, "stats");
                if (st != null)
                {
                    d.PowerGroup = MiniJson.Str(st, "power_sink_group", null);
                    double pw = MiniJson.Num(st, "required_power_mw", double.NaN);
                    if (double.IsNaN(pw)) pw = MiniJson.Num(st, "power_mw", double.NaN);
                    if (double.IsNaN(pw)) pw = MiniJson.Num(st, "power_idle_mw", 0);
                    d.PowerMW = (float)pw;
                    d.InventoryVolume = (float)MiniJson.Num(st, "inventory_max_volume", 0);
                    switch (d.Kind)
                    {
                        case "Thrust":
                            d.ThrustForceN = (float)MiniJson.Num(st, "force_n", 0);
                            d.ThrustMaxPowerMW = (float)MiniJson.Num(st, "max_power_mw", 0);
                            d.ThrustMinPowerMW = (float)MiniJson.Num(st, "min_power_mw", 0);
                            if (MiniJson.Str(st, "thruster_type", "") == "Hydrogen") d.ThrustMaxPowerMW = d.ThrustMinPowerMW = 0;   // burns hydrogen (tanks assumed full), not electricity
                            break;
                        case "Reactor":
                        case "HydrogenEngine":
                            d.GeneratorMW = (float)MiniJson.Num(st, "max_power_output_mw", MiniJson.Num(st, "max_output_mw", 0));
                            break;
                        case "Gyro":
                            d.GyroForce = (float)MiniJson.Num(st, "force_n", 0);
                            break;
                        case "BatteryBlock":
                            d.BatteryMaxMWh = (float)MiniJson.Num(st, "max_stored_mwh", 0);
                            d.BatteryMaxOutMW = (float)MiniJson.Num(st, "max_output_mw", MiniJson.Num(st, "max_power_output_mw", 0));
                            d.BatteryMaxInMW = (float)MiniJson.Num(st, "max_input_mw", 0);
                            d.BatteryInitialRatio = (float)MiniJson.Num(st, "initial_charge_ratio", 0);
                            break;
                        case "SensorBlock":
                            d.SensorMaxRange = (float)MiniJson.Num(st, "max_range_m", 0);
                            break;
                        case "TurretControlBlock":
                            d.TurretControlRange = (float)MiniJson.Num(st, "max_range_m", 0);
                            break;
                        case "Warhead":
                            d.WarheadRadius = (float)MiniJson.Num(st, "explosion_radius_m", 0);
                            d.WarheadDamage = (float)MiniJson.Num(st, "explosion_damage", 0);
                            break;
                    }
                    var wst = MiniJson.Obj(st, "weapon");
                    if (wst != null)
                    {
                        string wid = MiniJson.Str(st, "weapon_definition", d.Key);
                        WeaponDef wd;
                        if (!db.Weapons.TryGetValue(wid, out wd))
                        {
                            var src = (weaponsTop != null ? MiniJson.Obj(weaponsTop, wid) : null) ?? wst;
                            wd = BuildWeapon(db, wid, src, wst, ammoTop, defaulted);
                            db.Weapons[wid] = wd;
                        }
                        d.Weapon = wd;
                    }
                }
                db.Blocks[d.Key] = d;
            }
            return db;
        }

        static WeaponDef BuildWeapon(DefDb db, string id, Dictionary<string, object> src, Dictionary<string, object> blockStats,
                                     Dictionary<string, object> ammoTop, HashSet<string> defaulted)
        {
            var w = new WeaponDef();
            w.Id = id;
            w.RateOfFireRpm = (float)MiniJson.Num(src, "rate_of_fire_rpm", MiniJson.Num(blockStats, "rate_of_fire_rpm", 0));
            w.ShotsInBurst = (int)MiniJson.Num(src, "shots_in_burst", MiniJson.Num(blockStats, "shots_in_burst", 0));
            w.DeviateShotAngleDeg = (float)MiniJson.Num(src, "deviate_shot_angle_deg", MiniJson.Num(blockStats, "deviate_shot_angle_deg", 0));
            w.ShotDelayMs = (float)MiniJson.Num(src, "shot_delay_ms", MiniJson.Num(blockStats, "shot_delay_ms", 0));
            w.ReloadTimeMs = (float)MiniJson.Num(src, "reload_time_ms", MiniJson.Num(blockStats, "reload_time_ms", 0));
            var mags = MiniJson.Arr(src, "magazines") ?? MiniJson.Arr(blockStats, "magazines");
            var detail = MiniJson.Obj(src, "ammo_detail") ?? MiniJson.Obj(blockStats, "ammo_detail");
            if (mags == null || mags.Count == 0 || detail == null)
                throw new InvalidDataException("defs_stats.json: weapon " + id + " has no magazines/ammo_detail");
            string magId = null; Dictionary<string, object> md = null;
            foreach (object m in mags) { var mo = MiniJson.Obj(detail, (string)m); if (mo != null) { magId = (string)m; md = mo; break; } }
            if (md == null) throw new InvalidDataException("defs_stats.json: weapon " + id + " magazine not in ammo_detail");
            w.MagazineId = magId;
            w.MagazineCapacity = (int)MiniJson.Num(md, "magazine_capacity", 1);
            w.MagazineMass = (float)MiniJson.Num(md, "magazine_mass", 0);
            w.MagazineVolume = (float)MiniJson.Num(md, "magazine_volume", 0);

            string ammoId = MiniJson.Str(md, "ammo", magId);
            AmmoDef a;
            if (!db.Ammo.TryGetValue(ammoId + "@" + magId, out a))
            {
                var at = ammoTop != null ? MiniJson.Obj(ammoTop, ammoId) : null;
                a = new AmmoDef();
                a.Id = ammoId;
                a.IsMissile = MiniJson.Str(at, "kind", "Projectile") == "Missile";
                a.Speed = (float)MiniJson.Num(md, "speed", MiniJson.Num(at, "BasicProperties.DesiredSpeed", 0));
                a.MaxTrajectory = (float)MiniJson.Num(md, "max_range", MiniJson.Num(at, "BasicProperties.MaxTrajectory", 0));
                a.MassDamage = (float)MiniJson.Num(md, "damage_blocks", MiniJson.Num(at, "ProjectileProperties.ProjectileMassDamage", 0));
                a.HealthDamage = (float)MiniJson.Num(md, "damage_characters", MiniJson.Num(at, "ProjectileProperties.ProjectileHealthDamage", 0));
                a.ExplosiveDamageMultiplier = (float)MiniJson.Num(md, "explosive_damage_multiplier", MiniJson.Num(at, "BasicProperties.ExplosiveDamageMultiplier", 0));
                a.MissileInitialSpeed = (float)MiniJson.Num(md, "initial_speed", MiniJson.Num(at, "MissileProperties.MissileInitialSpeed", 0));
                a.MissileAcceleration = (float)MiniJson.Num(md, "acceleration", MiniJson.Num(at, "MissileProperties.MissileAcceleration", 0));
                a.MissileExplosionRadius = (float)MiniJson.Num(md, "explosion_radius", MiniJson.Num(at, "MissileProperties.MissileExplosionRadius", 0));
                a.MissileExplosionDamage = (float)MiniJson.Num(md, "explosion_damage", MiniJson.Num(at, "MissileProperties.MissileExplosionDamage", 0));
                a.MissileHealthPool = (float)MiniJson.Num(md, "health_pool", MiniJson.Num(at, "MissileProperties.MissileHealthPool", 0));
                a.MissileMass = (float)MiniJson.Num(md, "missile_mass", MiniJson.Num(at, "MissileProperties.MissileMass", 0));
                a.GravityEnabled = MiniJson.Bool(md, "gravity_enabled", MiniJson.Bool(at, "MissileProperties.MissileGravityEnabled", false));
                db.Ammo[ammoId + "@" + magId] = a;
                if (!db.Ammo.ContainsKey(ammoId)) db.Ammo[ammoId] = a;
            }
            w.Ammo = a;
            return w;
        }

        public BlockDef Get(string typeId, string subtype)
        {
            string key = typeId + "/" + (subtype ?? "");
            BlockDef d;
            if (Blocks.TryGetValue(key, out d)) return d;
            // a few defs_stats keys carry the full object builder prefix (e.g. MyObjectBuilder_Projector/SmallProjector)
            if (Blocks.TryGetValue("MyObjectBuilder_" + key, out d)) return d;
            throw new KeyNotFoundException("unknown block definition '" + key + "' (not in defs_stats.json)");
        }

        public bool TryGet(string typeId, string subtype, out BlockDef d)
        {
            string key = typeId + "/" + (subtype ?? "");
            return Blocks.TryGetValue(key, out d) || Blocks.TryGetValue("MyObjectBuilder_" + key, out d);
        }

        public int PriorityOf(string group)
        {
            int p;
            if (group != null && PowerPriority.TryGetValue(group, out p)) return p;
            throw new KeyNotFoundException("unknown power group '" + group + "'");
        }
    }
}
